/*
 * Morse Code — SOS via LED
 * LED on pin 13
 */

int ledPin = 13;
int dotLen  = 200;
int dashLen = 600;
int letterGap = 600;
int wordGap = 1400;

void dot() {
  digitalWrite(ledPin, HIGH); delay(dotLen);
  digitalWrite(ledPin, LOW);  delay(dotLen);
}

void dash() {
  digitalWrite(ledPin, HIGH); delay(dashLen);
  digitalWrite(ledPin, LOW);  delay(dotLen);
}

void setup() {
  pinMode(ledPin, OUTPUT);
  Serial.begin(115200);
  Serial.println("Morse SOS started");
}

void loop() {
  Serial.println("SOS ...");
  // S = . . .
  dot(); dot(); dot();
  delay(letterGap);
  // O = — — —
  dash(); dash(); dash();
  delay(letterGap);
  // S = . . .
  dot(); dot(); dot();
  delay(wordGap);
}
